import{_ as c,C as o,o as l,c as d,a6 as n,E as t,j as a,a as i}from"./chunks/framework.5dd0l9Wo.js";const w=JSON.parse('{"title":"Clickjacking","description":"Framing, UI redressing, frame busters, prefilled forms, and clickjacking chained with DOM XSS.","frontmatter":{"title":"Clickjacking","description":"Framing, UI redressing, frame busters, prefilled forms, and clickjacking chained with DOM XSS."},"headers":[],"relativePath":"clickjacking/index.md","filePath":"clickjacking/index.md"}'),p={name:"clickjacking/index.md"};function h(u,e,m,g,f,k){const s=o("LabGroup"),r=o("TopicComplete");return l(),d("div",null,[e[0]||(e[0]=n('<h1 id="clickjacking-·-the-case-of-the-invisible-trapdoor" tabindex="-1">Clickjacking · The Case of the Invisible Trapdoor <a class="header-anchor" href="#clickjacking-·-the-case-of-the-invisible-trapdoor" aria-label="Permalink to &quot;Clickjacking · The Case of the Invisible Trapdoor&quot;">​</a></h1><p class="wd-section-lede">Clickjacking (also known as a UI Redressing attack) does not break network encryption or exploit memory bugs. Instead, it tricks the human in front of the screen. An attacker loads a target website inside an invisible frame, places an enticing decoy button directly in front of it, and hijacks the user&#39;s authentic mouse click to trigger sensitive account actions.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Stencil Over the Contract.</strong> Imagine a salesperson hands you a fun crossword puzzle with a small cutout window where you are asked to write a checkmark to win a free coffee. Unknown to you, placed directly underneath the cardboard stencil is an official contract to transfer the title of your car—and your checkmark lands right on the signature line. You intended to claim a coffee, but your physical pen stroke signed away your property.</p></div><h2 id="case-file-1-tracing-the-transparent-iframe-heist" tabindex="-1">Case File #1: Tracing the Transparent Iframe Heist <a class="header-anchor" href="#case-file-1-tracing-the-transparent-iframe-heist" aria-label="Permalink to &quot;Case File #1: Tracing the Transparent Iframe Heist&quot;">​</a></h2><p>Let&#39;s see how an attacker turns a routine account settings page into an invisible trap.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You visit a promotional page offering a free prize. In the center of the page is a large, colorful button that says: <em>&quot;Click Here to Claim Free Gift!&quot;</em> Everything looks harmless and playful.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Attacker Page Does Behind the Scenes</span><p>Layered directly on top of the decoy button is an <code>&lt;iframe&gt;</code> loading the user&#39;s real account page on <code>https://target-bank.example/account/delete</code>. The iframe has <code>opacity: 0.0001</code> (virtually invisible) and a higher <code>z-index</code>:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Decoy UI Visible to Victim</span><span><span class="wd-code-input">Gold</span> = Invisible Iframe Layered on Top</span></div><span class="wd-code-dev">&lt;button style=&quot;position: absolute; top: 300px; left: 100px; z-index: 1;&quot;&gt;Claim Free Gift&lt;/button&gt;</span><br><span class="wd-code-input">&lt;iframe src=&quot;https://target-bank.example/account/delete&quot; style=&quot;opacity: 0.0001; position: absolute; top: 280px; left: 90px; z-index: 2;&quot;&gt;&lt;/iframe&gt;</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>Because the victim is logged into <code>target-bank.example</code>, the browser renders their authenticated account page inside the frame. When the user clicks the decoy button, the mouse click is intercepted by the invisible top layer—landing directly on the bank&#39;s &quot;Confirm Account Deletion&quot; button!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers send HTTP response headers that forbid third-party websites from framing sensitive pages. By setting <code>Content-Security-Policy: frame-ancestors &#39;none&#39;</code> (or legacy <code>X-Frame-Options: DENY</code>), the browser refuses to render the page inside any iframe.</p></div></div><h3 id="visual-comparison-decoy-surface-vs-invisible-trapdoor" tabindex="-1">Visual Comparison: Decoy Surface vs. Invisible Trapdoor <a class="header-anchor" href="#visual-comparison-decoy-surface-vs-invisible-trapdoor" aria-label="Permalink to &quot;Visual Comparison: Decoy Surface vs. Invisible Trapdoor&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer assumed that because the account deletion page is protected by CSRF tokens and requires an explicit button click, an attacker could never automate the action from another website.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The attacker never had to forge a request or steal a token. They simply framed the real page, made it invisible, and tricked the victim into performing the genuine physical click themselves.</p></div></div><hr><h2 id="the-ui-redress-layering-mechanism" tabindex="-1">The UI Redress Layering Mechanism <a class="header-anchor" href="#the-ui-redress-layering-mechanism" aria-label="Permalink to &quot;The UI Redress Layering Mechanism&quot;">​</a></h2><p>A clickjacking attack works by aligning layers in the browser&#39;s visual viewport:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Decoy Webpage</strong> Attacker displays tempting decoy UI (game, quiz, or prize button). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Authenticated Iframe</strong> Target website loaded invisibly via <code>opacity: 0.0001</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>3. Coordinate Alignment</strong> Target action button positioned precisely beneath the decoy cursor. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>4. Unwitting Click</strong> Victim clicks decoy; hit-test event lands on the transparent iframe. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Action Executed</strong> Target application processes legitimate authenticated click. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: Why Opacity is Used Instead of display:none</summary><p>If an attacker styles an iframe with <code>display: none</code> or <code>visibility: hidden</code>, the browser does not render the element in the layout tree and it cannot receive mouse events.</p><p>By setting <code>opacity: 0.0001</code>, the iframe remains fully rendered and active in the browser&#39;s hit-testing pipeline. The minuscule opacity value avoids browser rendering optimizations that might skip painting completely transparent elements.</p></details><hr><h2 id="prefilled-form-inputs-amp-csrf-protections" tabindex="-1">Prefilled Form Inputs &amp; CSRF Protections <a class="header-anchor" href="#prefilled-form-inputs-amp-csrf-protections" aria-label="Permalink to &quot;Prefilled Form Inputs &amp;amp; CSRF Protections&quot;">​</a></h2><p>Some web applications accept parameters from the URL to prefill forms (e.g. <code>?email=attacker@malicious.com</code>). When clickjacking is combined with URL prefilling, the attacker only needs to entice the user into a single click to submit the pre-populated form!</p><p>Even if the target form contains robust anti-CSRF tokens, the attack succeeds because the submission is generated natively inside the genuine, framed document.</p>',17)),t(s,{ids:"clickjacking-lab-prefilled-form-input, clickjacking-lab-basic-csrf-protected"}),e[1]||(e[1]=n(`<hr><h2 id="the-failure-of-javascript-frame-busters" tabindex="-1">The Failure of JavaScript Frame Busters <a class="header-anchor" href="#the-failure-of-javascript-frame-busters" aria-label="Permalink to &quot;The Failure of JavaScript Frame Busters&quot;">​</a></h2><p>Before standard HTTP security headers existed, developers attempted to block framing using client-side JavaScript &quot;frame buster&quot; scripts:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Naive frame-buster script</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (top </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> self) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  top.location </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> self.location;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>These scripts are easily defeated:</p><ul><li><strong>HTML5 Sandboxing:</strong> An attacker can frame the page with <code>&lt;iframe sandbox=&quot;allow-forms allow-scripts&quot;&gt;</code> while omitting <code>allow-top-navigation</code>, preventing the frame buster from redirecting the top-level window.</li><li><strong>Navigation Interception:</strong> The attacking parent window can listen to <code>onbeforeunload</code> and prompt the user to cancel any attempted redirection.</li></ul>`,6)),t(s,{ids:"clickjacking-lab-frame-buster-script"}),e[2]||(e[2]=a("hr",null,null,-1)),e[3]||(e[3]=a("h2",{id:"chaining-clickjacking-with-dom-xss",tabindex:"-1"},[i("Chaining Clickjacking with DOM XSS "),a("a",{class:"header-anchor",href:"#chaining-clickjacking-with-dom-xss","aria-label":'Permalink to "Chaining Clickjacking with DOM XSS"'},"​")],-1)),e[4]||(e[4]=a("p",null,[i("If a target page has a DOM-based XSS flaw that requires user interaction (such as an anchor tag with a "),a("code",null,"javascript:"),i(" URL or a button with an "),a("code",null,"onclick"),i(" handler), an attacker can supply the payload in the iframe's URL and use clickjacking to supply the necessary user activation.")],-1)),e[5]||(e[5]=a("p",null,"The victim clicks what they think is a harmless game button, triggering the client-side sink and executing the script.",-1)),t(s,{ids:"clickjacking-lab-exploiting-to-trigger-dom-based-xss"}),e[6]||(e[6]=a("hr",null,null,-1)),e[7]||(e[7]=a("h2",{id:"multi-step-confirmation-flows",tabindex:"-1"},[i("Multi-Step Confirmation Flows "),a("a",{class:"header-anchor",href:"#multi-step-confirmation-flows","aria-label":'Permalink to "Multi-Step Confirmation Flows"'},"​")],-1)),e[8]||(e[8]=a("p",null,'Many sensitive actions involve two steps: a first click to initiate the action and a second click in a confirmation modal. Clickjackers overcome this by creating multi-stage decoy games (like "Whack-a-Mole" or "Click twice to verify your age"), moving the decoy button between clicks to match the shifting coordinates of the modal dialog.',-1)),t(s,{ids:"clickjacking-lab-multistep"}),e[9]||(e[9]=n('<details class="details custom-block"><summary>⚙️ Defensive Headers: X-Frame-Options vs. CSP frame-ancestors</summary><ul><li><strong><code>X-Frame-Options: DENY</code>:</strong> Blocks all framing attempts on any origin.</li><li><strong><code>X-Frame-Options: SAMEORIGIN</code>:</strong> Permits framing only by pages on the exact same origin.</li><li><strong><code>Content-Security-Policy: frame-ancestors &#39;none&#39;</code>:</strong> The modern standard. Replaces <code>X-Frame-Options</code> and allows specifying exact allowed ancestor domains (<code>frame-ancestors &#39;self&#39; https://trusted-partner.com</code>).</li></ul><p>When both headers are present, modern browsers give precedence to CSP <code>frame-ancestors</code>.</p></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Detective&#39;s Defense Blueprint.</strong> Always send <code>Content-Security-Policy: frame-ancestors &#39;none&#39;</code> (or an explicit allow-list) on all authenticated pages. For legacy browser support, include <code>X-Frame-Options: DENY</code>. Never rely on client-side JavaScript frame-busting scripts. For highly sensitive operations like password changes or fund transfers, require re-authentication or multi-factor confirmation.</p></div>',2)),t(r,{"topic-id":"clickjacking",label:"Mark clickjacking complete"})])}const v=c(p,[["render",h]]);export{w as __pageData,v as default};
